// Compute the threshold date (today + 14 days)
const d = new Date();
d.setDate(d.getDate() + 14);
return [{ json: { until: d.toISOString().slice(0, 10), today: new Date().toISOString().slice(0, 10) } }];

// Explode + compute days remaining + decide whether to notify (J-14, J-7, J-3, J-1, J0)
const rows = Array.isArray($json) ? $json : ($json.body || []);
const now = new Date(); now.setHours(0, 0, 0, 0);
const out = [];
const LABELS = {
  tva_ca3: 'TVA CA3', tva_ca12: 'TVA CA12', is: 'Acompte IS',
  liasse: 'Liasse fiscale', cfe: 'CFE', cvae: 'CVAE', das2: 'DAS2',
};
for (const r of rows) {
  const dl = new Date(r.deadline);
  const days = Math.ceil((dl.getTime() - now.getTime()) / 86400000);
  if (![14, 7, 3, 1, 0].includes(days)) continue;
  let prefix = '⏰', priority = 'normal';
  if (days === 0) { prefix = '🔴'; priority = 'urgent'; }
  else if (days <= 1) { prefix = '🚨'; priority = 'urgent'; }
  else if (days <= 3) { prefix = '⚠️'; priority = 'high'; }
  else if (days <= 7) { prefix = '🔔'; priority = 'high'; }
  out.push({ json: {
    user_id: r.user_id,
    declaration_id: r.id,
    title: `${prefix} ${LABELS[r.type] || r.type} dans ${days}j`,
    body: `${LABELS[r.type] || r.type} ${r.period} · deadline ${new Date(r.deadline).toLocaleDateString('fr-FR')}`,
    priority,
    days,
  } });
}
if (out.length === 0) return [];
return out;
